function makeScopedDocument(root, realDocument){
  return {
    getElementById(id){ return root.querySelector('#'+CSS.escape(id)); },
    querySelector(sel){ return root.querySelector(sel); },
    querySelectorAll(sel){ return root.querySelectorAll(sel); },
    createElement(tag){ return realDocument.createElement(tag); },
    addEventListener(type, handler, options){ return root.addEventListener(type, handler, options); },
    removeEventListener(type, handler, options){ return root.removeEventListener(type, handler, options); },
    get body(){ return root; },
    get documentElement(){ return root; }
  };
}
function makeScopedWindow(root, realWindow){
  return {
    scrollTo(arg1,arg2){
      if(typeof arg1==='object') root.scrollTo(arg1);
      else root.scrollTo(arg1||0,arg2||0);
    },
    print(){ realWindow.print(); }
  };
}


