function collectAnswers() {
  const answers = {};
  document.querySelectorAll('input[type="radio"][name^="t"]:checked').forEach(el => answers[el.name] = el.value);
  return answers;
}

function saveAnswers() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(collectAnswers()));
}

function restoreAnswers() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || "{}");
    Object.entries(saved).forEach(([name, value]) => {
      const el = document.querySelector(`input[name="${name}"][value="${value}"]`);
      if (el) el.checked = true;
    });
  } catch (e) {
    console.warn("저장된 응답을 불러오지 못했습니다.", e);
  }
}

function calculate() {
  const results = [];
  let overallAnswered = 0;
  let completedCount = 0;

  for (let type = 1; type <= 9; type++) {
    let total = 0;
    let answered = 0;

    for (let q = 1; q <= 15; q++) {
      const checked = document.querySelector(`input[name="t${type}q${q}"]:checked`);
      if (checked) {
        total += Number(checked.value);
        answered++;
      }
    }

    const avg = answered ? total / answered : 0;
    const complete = answered === 15;
    overallAnswered += answered;
    if (complete) completedCount++;

    document.getElementById(`total${type}`).textContent = total;
    document.getElementById(`avg${type}`).textContent = avg.toFixed(2);
    document.getElementById(`answered${type}`).textContent = answered;
    document.getElementById(`inlineTotal${type}`).textContent = total;
    document.getElementById(`inlineAvg${type}`).textContent = avg.toFixed(2);
    document.getElementById(`inlineAnswered${type}`).textContent = answered;

    const card = document.getElementById(`resultCard${type}`);
    card.classList.toggle("complete", complete);

    const tab = document.querySelector(`[data-tab="${type}"]`);
    if (tab) tab.classList.toggle("complete", complete);

    const interpretationBox = document.getElementById(`interpretation${type}`);
    const resultCopy = document.getElementById(`resultCopy${type}`);

    if (complete) {
      const interpreted = getInterpretation(type, total);
      interpretationBox.innerHTML = `
        <span class="range">${interpreted.range}</span>
        <span class="message">${interpreted.message}</span>
        ${confusionHTML(type)}
      `;
      resultCopy.innerHTML = `<span class="result-range">${interpreted.range}</span><br>${interpreted.message}`;
    } else {
      interpretationBox.innerHTML = `<div class="pending">${15 - answered}문항이 남았습니다. 모두 선택하면 점수 해석이 표시됩니다.</div>`;
      resultCopy.textContent = answered ? `${15 - answered}문항 남음` : "완료 후 해석 표시";
    }

    results.push({type, total, answered, avg, complete});
  }

  document.getElementById("overallAnswered").textContent = overallAnswered;
  document.getElementById("completedTypes").textContent = completedCount;

  const completed = results.filter(r => r.complete);
  const rankText = document.getElementById("rankText");

  if (!completed.length) {
    rankText.textContent = "아직 15문항을 모두 완료한 유형이 없습니다.";
  } else {
    const sorted = [...completed].sort((a,b) => b.total - a.total || a.type - b.type);
    rankText.textContent = sorted.map((r,i) => `${i+1}위 · ${r.type}번 ${r.total}점`).join("  &gt;  ");
  }
}

document.addEventListener("change", e => {
  if (e.target.matches('input[type="radio"][name^="t"]')) {
    calculate();
    saveAnswers();
  }
});

document.getElementById("resetBtn").addEventListener("click", () => {
  if (!confirm("입력한 135문항의 응답을 모두 초기화할까요?")) return;
  document.querySelectorAll('input[type="radio"][name^="t"]').forEach(el => el.checked = false);
  localStorage.removeItem(STORAGE_KEY);
  calculate();
  window.scrollTo({top:0,behavior:"smooth"});
});

restoreAnswers();
calculate();


