const QUICK_TYPE_MAP={
  A1:7,A2:8,A3:3,
  B1:9,B2:4,B3:5,
  C1:2,C2:6,C3:1
};
const QUICK_TYPE_NAMES={
  1:'개혁자',2:'조력자',3:'성취자',4:'개인주의자',5:'탐구자',
  6:'충실가',7:'열정가',8:'도전자',9:'평화주의자'
};
let quickChoice={alpha:null,number:null};

function setCheckMode(mode,push=false){
  if(!['start','select','quick','detail'].includes(mode)) mode='start';
  document.querySelectorAll('#page-check .check-mode-tab').forEach(btn=>{
    const on=btn.dataset.checkMode===mode;
    btn.classList.toggle('active',on);
    btn.setAttribute('aria-selected',on?'true':'false');
  });
  document.querySelectorAll('#page-check [data-check-mode-panel]').forEach(panel=>{
    panel.classList.toggle('active',panel.dataset.checkModePanel===mode);
  });
  const page=document.getElementById('page-check');
  if(page) page.scrollTop=0;
  if(push){
    try{history.replaceState(null,'',mode==='detail'?'#check-detail':'#check');}catch(e){}
  }
}

function getQuickWinner(group){
  const values = group==='alpha' ? ['A','B','C'] : ['1','2','3'];
  const counts = Object.fromEntries(values.map(v=>[v,0]));

  document.querySelectorAll(`#page-check .quick-item-check[data-quick-group="${group}"]:checked`)
    .forEach(input=>{
      const value=String(input.dataset.quickValue);
      if(value in counts) counts[value]+=1;
    });

  const ranked=values
    .map(value=>({value,count:counts[value]}))
    .sort((a,b)=>b.count-a.count);

  if(ranked[0].count===0) return null;
  if(ranked[0].count===ranked[1].count) return null;
  return ranked[0].value;
}

function updateQuickCardStates(){
  document.querySelectorAll('#page-check .quick-choice-card').forEach(card=>{
    const count=card.querySelectorAll('.quick-item-check:checked').length;
    card.classList.toggle('has-checked',count>0);
  });
}

function updateQuickResult(){
  const empty=document.getElementById('quickResultEmpty');
  const content=document.getElementById('quickResultContent');
  if(!empty || !content) return;

  quickChoice.alpha=getQuickWinner('alpha');
  quickChoice.number=getQuickWinner('number');
  updateQuickCardStates();

  const checkedItems=[...document.querySelectorAll('#page-check .quick-item-check:checked')]
    .map(input=>input.dataset.quickItem);

  try{
    localStorage.setItem('enneagram_quick_check_v2',JSON.stringify(checkedItems));
  }catch(e){}

  if(!quickChoice.alpha || !quickChoice.number){
    empty.hidden=false;
    content.hidden=true;
    return;
  }

  const combo=quickChoice.alpha+quickChoice.number;
  const type=QUICK_TYPE_MAP[combo];
  document.getElementById('quickResultType').textContent=type;
  document.getElementById('quickResultName').textContent=`${QUICK_TYPE_NAMES[type]} 유형`;
  document.getElementById('quickResultCombo').textContent=combo;
  document.getElementById('quickGoHandbook').dataset.type=type;
  empty.hidden=true;
  content.hidden=false;
}

function resetQuickCheck(){
  document.querySelectorAll('#page-check .quick-item-check').forEach(input=>{
    input.checked=false;
  });
  quickChoice={alpha:null,number:null};
  try{
    localStorage.removeItem('enneagram_quick_check_v2');
    localStorage.removeItem('enneagram_quick_check_v1');
  }catch(e){}
  updateQuickResult();

  const page=document.getElementById('page-check');
  if(page) page.scrollTo({top:0,behavior:'smooth'});
}

function restoreQuickCheck(){
  try{
    const saved=JSON.parse(localStorage.getItem('enneagram_quick_check_v2')||'[]');
    if(Array.isArray(saved)){
      const savedSet=new Set(saved);
      document.querySelectorAll('#page-check .quick-item-check').forEach(input=>{
        input.checked=savedSet.has(input.dataset.quickItem);
      });
    }
  }catch(e){}
  updateQuickResult();
}

document.querySelectorAll('#page-check .check-mode-tab').forEach(btn=>{
  btn.addEventListener('click',()=>setCheckMode(btn.dataset.checkMode,true));
});
document.querySelectorAll('#page-check .quick-item-check').forEach(input=>{
  input.addEventListener('change',updateQuickResult);
});
document.getElementById('quickReset')?.addEventListener('click',resetQuickCheck);
restoreQuickCheck();


