/* =========================================================
   유형 체크 흐름: 시작(검사 선택) > 간편 검사
                          > 헷갈리는 유형 고르기 > 선택 유형 문항 > 결과
   ========================================================= */
const CHECK_TYPE_NAMES={1:'개혁가',2:'조력가',3:'성취자',4:'개인주의자',5:'탐구자',6:'충실가',7:'열정가',8:'도전자',9:'평화주의자'};
const CHECK_SELECTION_KEY='enneagram_detail_selection';
const CHECK_SELECTION_SCHEMA=1;
const CHECK_ANSWERS_KEY='enneagram_types_1_to_9_answers_v2';

function normalizeTypeList(list){
  return [...new Set((Array.isArray(list)?list:[]).map(Number).filter(n=>Number.isInteger(n)&&n>=1&&n<=9))].sort((a,b)=>a-b);
}

function writeCheckSelection(types){
  try{
    localStorage.setItem(CHECK_SELECTION_KEY,JSON.stringify({
      schemaVersion:CHECK_SELECTION_SCHEMA,
      types:normalizeTypeList(types),
      updatedAt:new Date().toISOString()
    }));
  }catch(e){}
}

/* schemaVersion 1: {schemaVersion, types:[1..9], updatedAt}
   이전 구조(enneagramSelectedDiagnosisType: 단일 번호 문자열)는 types:[n]으로 옮긴다. */
function readCheckSelection(){
  try{
    const raw=localStorage.getItem(CHECK_SELECTION_KEY);
    if(raw){
      const saved=JSON.parse(raw);
      if(saved && saved.schemaVersion===CHECK_SELECTION_SCHEMA) return normalizeTypeList(saved.types);
    }
    const legacy=Number(localStorage.getItem('enneagramSelectedDiagnosisType'));
    if(legacy>=1 && legacy<=9){
      writeCheckSelection([legacy]);
      return [legacy];
    }
  }catch(e){}
  return [];
}

let checkSelection=readCheckSelection();

function answeredCount(type){
  return document.querySelectorAll(`#page-check input[type="radio"][name^="t${type}q"]:checked`).length;
}

/* 간편 검사 저장값(enneagram_quick_check_v2)으로 결과 유형 계산 — getQuickWinner와 같은 규칙 */
function getSavedQuickType(){
  try{
    const saved=JSON.parse(localStorage.getItem('enneagram_quick_check_v2')||'[]');
    if(!Array.isArray(saved)) return null;
    const pick=(group,values)=>{
      const ranked=values
        .map(v=>({v,c:saved.filter(id=>String(id).startsWith(`${group}-${v}-`)).length}))
        .sort((x,y)=>y.c-x.c);
      return ranked[0].c>0 && ranked[0].c!==ranked[1].c ? ranked[0].v : null;
    };
    const alpha=pick('alpha',['A','B','C']);
    const number=pick('number',['1','2','3']);
    return alpha && number ? (QUICK_TYPE_MAP[alpha+number]||null) : null;
  }catch(e){ return null; }
}

/* 정식 검사에서 15문항을 모두 답한 유형 (저장값 기준) */
function getCompletedDetailTypes(){
  try{
    const saved=JSON.parse(localStorage.getItem(CHECK_ANSWERS_KEY)||'{}');
    const done=[];
    for(let t=1;t<=9;t++){
      let n=0;
      for(let q=1;q<=15;q++) if(saved[`t${t}q${q}`]) n++;
      if(n===15) done.push(t);
    }
    return done;
  }catch(e){ return []; }
}

function renderCheckSelect(){
  const grid=document.getElementById('checkSelectGrid');
  if(!grid) return;
  grid.querySelectorAll('[data-select-type]').forEach(btn=>{
    const on=checkSelection.includes(Number(btn.dataset.selectType));
    btn.classList.toggle('active',on);
    btn.setAttribute('aria-pressed',on?'true':'false');
  });
  const count=document.getElementById('checkSelectCount');
  if(count){
    count.textContent=checkSelection.length
      ? `${checkSelection.length}개 선택 · ${checkSelection.length*15}문항`
      : '선택한 유형이 없어요';
  }
  const all=document.getElementById('checkSelectAll');
  if(all) all.textContent=checkSelection.length===9 ? '선택 모두 해제' : '9개 모두 선택';
  const start=document.getElementById('checkSelectStart');
  if(start) start.disabled=!checkSelection.length;
}

function renderCheckDetailSteps(target){
  const steps=document.getElementById('checkDetailSteps');
  const pager=document.getElementById('checkDetailPager');
  if(!steps || !pager) return;

  const m=String(target).match(/^detail-([1-9])$/);
  const currentType=m ? Number(m[1]) : null;

  steps.innerHTML=checkSelection.map(t=>{
    const count=answeredCount(t);
    const on=t===currentType;
    return `<button type="button" class="check-detail-step${on?' active':''}${count===15?' complete':''}" data-check-go="detail-${t}"${on?' aria-current="step"':''}>`
      +`<span class="check-detail-step-no">${t}</span><span>${CHECK_TYPE_NAMES[t]}</span>`
      +`<span class="check-detail-step-meta">${count}/15</span></button>`;
  }).join('')
  +`<button type="button" class="check-detail-step check-detail-step-result${target==='result'?' active':''}" data-check-go="result"${target==='result'?' aria-current="step"':''}>결과</button>`;

  if(!currentType){
    pager.hidden=true;
    pager.innerHTML='';
    return;
  }
  const idx=checkSelection.indexOf(currentType);
  const prev=checkSelection[idx-1];
  const next=checkSelection[idx+1];
  pager.hidden=false;
  pager.innerHTML=
    `<span class="check-detail-progress">${idx+1} / ${checkSelection.length} 유형</span>`
    +'<div class="check-detail-pager-actions">'
    +(prev ? `<button type="button" class="check-flow-secondary" data-check-go="detail-${prev}">이전 · ${prev}번</button>` : '')
    +(next
      ? `<button type="button" class="check-flow-primary" data-check-go="detail-${next}">다음 · ${next}번 ${CHECK_TYPE_NAMES[next]}</button>`
      : '<button type="button" class="check-flow-primary" data-check-go="result">결과 보기</button>')
    +'</div>';
}

function applyDetailedCheckTarget(target){
  const root=document.getElementById('page-check');
  if(!root) return;

  const sections=root.querySelectorAll('.type-section');
  const summary=root.querySelector('#summary');

  if(target==='result'){
    sections.forEach(s=>s.classList.add('shell-check-hidden'));
    if(summary) summary.classList.remove('shell-check-hidden');
    /* 결과 카드는 고른 유형 + 이미 완료한 유형만 */
    const visible=new Set(checkSelection.concat(getCompletedDetailTypes()));
    for(let t=1;t<=9;t++){
      const card=document.getElementById(`resultCard${t}`);
      if(card) card.hidden=visible.size>0 && !visible.has(t);
    }
    renderCheckDetailSteps(target);
    return;
  }

  const m=String(target).match(/^detail-([1-9])$/);
  const n=m ? m[1] : String(checkSelection[0]||1);
  sections.forEach(s=>{
    s.classList.toggle('shell-check-hidden',s.id!==`type${n}`);
  });
  if(summary) summary.classList.add('shell-check-hidden');
  renderCheckDetailSteps(`detail-${n}`);
}

function showCheckTarget(target='start',push=true){
  if(!/^detail-[1-9]$/.test(target) && !['start','select','quick','result'].includes(target)) target='start';

  /* 선택 없이 문항/결과로 바로 들어오면(직접 링크 등) 해당 유형이나 완료 유형을 선택에 넣는다 */
  const direct=String(target).match(/^detail-([1-9])$/);
  if(direct && !checkSelection.includes(Number(direct[1]))){
    checkSelection=normalizeTypeList(checkSelection.concat(Number(direct[1])));
    writeCheckSelection(checkSelection);
  }
  if(target==='result' && !checkSelection.length){
    checkSelection=getCompletedDetailTypes();
  }

  currentCheckTarget=target;
  activateBasePage('check');

  const mobileTitle=document.getElementById('shellMobileTitle');
  if(target==='start' || target==='select' || target==='quick'){
    setCheckMode(target,false);
    if(target==='select'){
      const hint=document.getElementById('checkSelectHint');
      const quickType=getSavedQuickType();
      if(!checkSelection.length && quickType){
        checkSelection=[quickType];
        writeCheckSelection(checkSelection);
        if(hint){
          hint.textContent=`간편 검사 결과인 ${quickType}번 ${CHECK_TYPE_NAMES[quickType]}을(를) 미리 골라뒀어요. 함께 헷갈리는 유형을 더 골라보세요.`;
          hint.hidden=false;
        }
      }else if(hint){
        hint.hidden=true;
      }
      renderCheckSelect();
    }
    mobileTitle.textContent={start:'유형 체크',select:'유형 체크 · 유형 고르기',quick:'유형 체크 · 간편 검사'}[target];
  }else{
    setCheckMode('detail',false);
    applyDetailedCheckTarget(target);
    mobileTitle.textContent=target==='result' ? '유형 체크 · 점수 결과' : `유형 체크 · 정식 검사 ${target.split('-')[1]}번`;
  }
  document.getElementById('page-check')?.scrollTo({top:0});

  if(push){
    const h=target==='start' ? '#check' : target==='result' ? '#check-result' : `#check-${target}`;
    history.replaceState(null,'',h);
  }
  closeShellMenu();
}

/* 흐름 이동 버튼(data-check-go)과 유형 고르기는 한곳에서 처리 */
document.getElementById('page-check')?.addEventListener('click',e=>{
  const go=e.target.closest('[data-check-go]');
  if(go){
    e.preventDefault();
    showCheckTarget(go.dataset.checkGo);
    return;
  }
  const typeBtn=e.target.closest('[data-select-type]');
  if(typeBtn){
    const t=Number(typeBtn.dataset.selectType);
    checkSelection=checkSelection.includes(t) ? checkSelection.filter(x=>x!==t) : normalizeTypeList(checkSelection.concat(t));
    writeCheckSelection(checkSelection);
    document.getElementById('checkSelectHint')?.setAttribute('hidden','');
    renderCheckSelect();
  }
});
document.getElementById('checkSelectAll')?.addEventListener('click',()=>{
  checkSelection=checkSelection.length===9 ? [] : [1,2,3,4,5,6,7,8,9];
  writeCheckSelection(checkSelection);
  renderCheckSelect();
});
document.getElementById('checkSelectStart')?.addEventListener('click',()=>{
  if(checkSelection.length) showCheckTarget(`detail-${checkSelection[0]}`);
});
/* 문항 응답 시 진행 상황(n/15) 갱신 */
document.getElementById('page-check')?.addEventListener('change',e=>{
  if(e.target.matches('input[type="radio"][name^="t"]') && /^(detail-|result$)/.test(currentCheckTarget)){
    renderCheckDetailSteps(currentCheckTarget);
  }
});


function setOverviewSidebarActive(key){
  document.querySelectorAll('.shell-overview-target').forEach(b=>{
    b.classList.toggle('active',b.dataset.overviewTarget===key);
  });
}
function showOverviewSection(key='basics',push=true){
  if(!Object.prototype.hasOwnProperty.call(OVERVIEW_TITLES,key)) key='basics';
  currentOverview=key;
  activateBasePage('overview');
  setOverviewSidebarActive(key);

  document.querySelectorAll('#page-overview .overview-panel[data-overview-key]').forEach(panel=>{
    panel.classList.toggle('active',panel.dataset.overviewKey===key);
  });

  document.getElementById('shellMobileTitle').textContent='에니어그램 이해 · '+OVERVIEW_TITLES[key];
  const page=document.getElementById('page-overview');
  page?.scrollTo({top:0});
  if(push) history.replaceState(null,'',`#overview-${key}`);
  closeShellMenu();
}

function showHandbookType(n,push=true){
  n=Number(n);
  if(!Number.isInteger(n)||n<1||n>9) n=1;
  currentType=n;
  activateBasePage('handbook');

document.querySelectorAll('.shell-handbook-type').forEach(b=>{
    b.classList.toggle('active',Number(b.dataset.type)===n);
  });

  const root=document.getElementById('page-handbook');
  if(root && typeof root.__showType==='function'){
    root.__showType(n);
  }else if(root){
    root.querySelectorAll('.type-page').forEach(el=>{
      el.classList.toggle('shell-type-hidden',el.dataset.type!==String(n));
    });
  }

  document.getElementById('shellMobileTitle').textContent='유형별 핸드북 · '+TYPE_LABELS[n];
  if(push) history.replaceState(null,'','#handbook-'+n);
  closeShellMenu();
}


function setCompareSidebarActive(key){
  document.querySelectorAll('.shell-compare-target').forEach(b=>{
    b.classList.toggle('active',b.dataset.compareTarget===key);
  });
}
function showCompareSection(key='glance',push=true){
  if(!Object.prototype.hasOwnProperty.call(COMPARE_TITLES,key)) key='glance';
  currentCompare=key;
  activateBasePage('compare');
  setCompareSidebarActive(key);

  document.querySelectorAll('#page-compare [data-compare-panel]').forEach(panel=>{
    panel.classList.toggle('active',panel.dataset.comparePanel===key);
  });

  document.getElementById('shellMobileTitle').textContent='전체 유형 비교 · '+COMPARE_TITLES[key];
  document.getElementById('page-compare')?.scrollTo({top:0});
  if(push) history.replaceState(null,'',`#compare-${key}`);
  closeShellMenu();
}

function setSharingSidebarActive(index){
  document.querySelectorAll('.shell-sharing-topic').forEach(b=>{
    b.classList.toggle('active',Number(b.dataset.topicIndex)===Number(index));
  });
}
function showSharingTopic(index=0,push=true){
  index=Number(index);
  if(!Number.isInteger(index)||index<0||index>=SHARING_TITLES.length) index=0;
  currentSharingTopic=index;
  activateBasePage('sharing');
  setSharingSidebarActive(index);

  const root=document.getElementById('page-sharing');
  if(root && typeof root.__showTopic==='function') root.__showTopic(index);

  document.getElementById('shellMobileTitle').textContent='나를 돌아보기 · '+SHARING_TITLES[index];
  if(push) history.replaceState(null,'',`#sharing-${index+1}`);
  closeShellMenu();
}


/* 하위 메뉴가 있는 대메뉴는 전체 행을 눌러 첫 번째 세부 화면을 열고 메뉴를 펼칩니다. */
function openParentGroup(groupId,firstAction){
  firstAction();
  document.querySelectorAll('.shell-menu-group').forEach(group=>{
    if(group.querySelector('.shell-submenu')) group.classList.toggle('open',group.id===groupId);
  });
  const hasSubmenu=!!document.getElementById(groupId)?.querySelector('.shell-submenu');
  if(hasSubmenu && window.matchMedia('(max-width:1000px)').matches) openShellMenu();
}

