/* 홈 CTA: 나의 유형 찾기 > 유형 체크 시작 화면 / 내 결과 보기 > 저장된 결과
   결과가 없으면 두 번째 버튼은 홈의 9가지 유형 섹션으로 안내한다. */
function getSavedCheckState(){
  const detailDone=getCompletedDetailTypes();
  const quickType=getSavedQuickType();
  return {detailDone,quickType,hasResult:detailDone.length>0 || !!quickType};
}

function openSavedResult(){
  const state=getSavedCheckState();
  if(state.detailDone.length) showCheckTarget('result');
  else if(state.quickType) showCheckTarget('quick');
  else document.getElementById('home-types')?.scrollIntoView({behavior:'smooth',block:'start'});
}

function syncHomeResultButtons(){
  const {hasResult}=getSavedCheckState();
  document.querySelectorAll('#page-home [data-home-action="result"]').forEach(btn=>{
    btn.textContent=hasResult ? '내 결과 보기' : '9가지 유형 둘러보기';
    btn.setAttribute('href',hasResult ? '#check-result' : '#home-types');
  });
}

/* 홈 '이어서 보기': 검사 결과·내 유형·성찰 기록이 있을 때만 노출 */
function renderHomeContinue(){
  const section=document.getElementById('home-continue');
  const list=document.getElementById('homeContinueList');
  if(!section || !list) return;

  const {detailDone,quickType}=getSavedCheckState();
  const readJSON=(k,fb)=>{try{const v=localStorage.getItem(k);return v?JSON.parse(v):fb;}catch(e){return fb;}};
  const myType=Number(readJSON('enneagram_my_type_v1',''));
  const reflections=readJSON('enneagram_reflections_v1',[]);
  const cards=[];

  if(detailDone.length){
    cards.push({label:'정식 검사 결과',title:`${detailDone.length}개 유형 점수 확인`,desc:'완료한 유형의 점수 구간 해석을 다시 볼 수 있어요.',action:'check-result'});
  }else if(quickType){
    cards.push({label:'간편 검사 결과',title:`${quickType}번 ${CHECK_TYPE_NAMES[quickType]}`,desc:'헷갈린다면 정식 검사로 가까운 유형을 함께 확인해보세요.',action:'check-quick'});
  }
  if(myType>=1 && myType<=9){
    cards.push({label:'내가 고른 유형',title:`${myType}번 ${CHECK_TYPE_NAMES[myType]} 핸드북`,desc:'핵심 패턴과 실제 모습, 성장 방향을 이어서 읽어보세요.',action:`handbook-${myType}`});
  }
  if(Array.isArray(reflections) && reflections.length){
    cards.push({label:'성찰 기록',title:`기록 ${reflections.length}개`,desc:'반복해서 등장한 단서를 나의 공간에서 모아보세요.',action:'myspace-reflection'});
  }

  section.hidden=!cards.length;
  const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  list.innerHTML=cards.map(c=>
    `<button class="continue-card" data-home-continue="${esc(c.action)}" type="button">`
    +`<span class="continue-label">${esc(c.label)}</span><strong>${esc(c.title)}</strong><span class="continue-desc">${esc(c.desc)}</span></button>`
  ).join('');
}

document.getElementById('page-home')?.addEventListener('click',e=>{
  const action=e.target.closest('[data-home-action]');
  if(action){
    e.preventDefault();
    if(action.dataset.homeAction==='find') showCheckTarget('start');
    else openSavedResult();
    return;
  }
  const more=e.target.closest('[data-home-more]');
  if(more){
    const key=more.dataset.homeMore;
    if(key==='overview') showOverviewSection('basics');
    else if(key==='handbook') showHandbookType(1);
    else if(key==='compare') showCompareSection('glance');
    return;
  }
  const cont=e.target.closest('[data-home-continue]');
  if(cont){
    const key=cont.dataset.homeContinue;
    const m=key.match(/^handbook-([1-9])$/);
    if(key==='check-result') showCheckTarget('result');
    else if(key==='check-quick') showCheckTarget('quick');
    else if(m) showHandbookType(Number(m[1]));
    else if(key==='myspace-reflection' && typeof showMySpaceSection==='function') showMySpaceSection('reflection');
  }
});

function refreshHome(){
  syncHomeResultButtons();
  renderHomeContinue();
}
refreshHome();

/* 직접 링크 */
const hash=location.hash.slice(1);
let match=null;
if(hash==='home' || hash===''){
  showHomePage(false);
}else if((match=hash.match(/^overview-(basics|core|centers|variation|growth|use)$/))){
  showOverviewSection(match[1],false);
}else if(hash==='overview'){
  showOverviewSection('basics',false);
}else if((match=hash.match(/^compare-(glance|motives|centers|hornevian|harmonic|situations|confused)$/))){
  showCompareSection(match[1],false);
}else if(hash==='compare'){
  showCompareSection('glance',false);
}else if((match=hash.match(/^handbook-([1-9])$/))){
  showHandbookType(Number(match[1]),false);
}else if((match=hash.match(/^check-detail-([1-9])$/))){
  showCheckTarget('detail-'+match[1],false);
}else if(hash==='check-result'){
  showCheckTarget('result',false);
}else if(hash==='check-quick'){
  showCheckTarget('quick',false);
}else if(hash==='check-select' || hash==='check-detail'){
  showCheckTarget('select',false);
}else if(hash==='check'){
  showCheckTarget('start',false);
}else if((match=hash.match(/^sharing-([1-9])$/))){
  showSharingTopic(Number(match[1])-1,false);
}else if(hash==='sharing'){
  showSharingTopic(0,false);
}else if(hash==='handbook'){
  showHandbookType(1,false);
}else{
  showHomePage(false);
}
